import { tv, type VariantProps } from "@/lib/beton/tv";

export const separator = tv({
  base: "shrink-0 border-0 bg-border",
  variants: {
    orientation: {
      horizontal: "w-full",
      vertical: "self-stretch",
    },
    size: {
      sm: "",
      md: "",
      lg: "",
    },
  },
  compoundVariants: [
    { orientation: "horizontal", size: "sm", class: "h-0.5" },
    { orientation: "horizontal", size: "md", class: "h-0.75" },
    { orientation: "horizontal", size: "lg", class: "h-1.25" },
    { orientation: "vertical", size: "sm", class: "w-0.5" },
    { orientation: "vertical", size: "md", class: "w-0.75" },
    { orientation: "vertical", size: "lg", class: "w-1.25" },
  ],
  defaultVariants: {
    orientation: "horizontal",
    size: "md",
  },
});

export type SeparatorVariants = VariantProps<typeof separator>;

import { separator, type SeparatorVariants } from "@/lib/beton/recipes/separator.recipe";
import type { ComponentProps } from "react";
import { renderElement, type RenderProp } from "@/lib/beton/render-element";

export interface SeparatorProps extends ComponentProps<"div">, SeparatorVariants {
  /**
   * A decorative separator is hidden from assistive technology. Set to `false`
   * when the separator divides meaningful groups of content.
   */
  decorative?: boolean;
  render?: RenderProp;
}

export function Separator({
  orientation = "horizontal",
  size = "md",
  decorative = true,
  className,
  render,
  ...props
}: SeparatorProps) {
  const semantics = decorative
    ? { role: "none" }
    : { role: "separator", "aria-orientation": orientation };

  return renderElement(
    "div",
    {
      ...semantics,
      ...props,
      "data-orientation": orientation,
      "data-size": size,
      className: separator({ orientation, size, class: className }),
    },
    render,
  );
}
